fulfill.run:
const re = $self.address.entire
const STORAGE_KEY = 'devtool_cookie_sync'
const DEFAULT_TARGETS = [
  { id: 'localhost-http', domain: 'localhost', protocol: 'http' },
  { id: '127-http', domain: '127.0.0.1', protocol: 'http' },
]
$self.state = $observable({ targets: [], syncing: false })
$self.saveCookieSync = async (targets) => {
  await $chrome.storage.local.set({ [STORAGE_KEY]: { targets: JSON.parse(JSON.stringify(targets || [])) } })
}
$self.loadCookieSync = async () => {
  try {
    const res = await $chrome.storage.local.get(STORAGE_KEY)
    const s = res[STORAGE_KEY]
    if (!s || !s.targets || s.targets.length === 0) {
      $self.state.targets = DEFAULT_TARGETS.map((t) => ({ ...t }))
      await $self.saveCookieSync($self.state.targets)
    } else {
      $self.state.targets = s.targets
    }
  } catch (e) {
    $logger.error('加载 Cookie 同步配置失败', e)
    $message.error('加载 Cookie 同步配置失败')
  }
}
$self.showAddOrUpdateDialog = (row) => {
  const dialog = $self.query(re + '.editDialog').take()
  if (dialog) {
    dialog.value = row ? { id: row.id, domain: row.domain, protocol: row.protocol } : { protocol: 'http' }
    dialog.setComponentProps({ open: true, title: row ? '编辑同步目标' : '新增同步目标' })
  }
}
$self.handleDelete = async (row) => {
  if (!row) return
  const list = $self.state.targets.filter((t) => t.id !== row.id)
  try {
    await $self.saveCookieSync(list)
    $self.state.targets = list
    $message.success('目标已删除')
  } catch (e) {
    $message.error('删除失败')
  }
}
$self.handleSyncNow = async () => {
  if ($self.state.targets.length === 0) {
    $message.warning('请先配置同步目标域名')
    return
  }
  const urlField = $self.query(re + '.toolbarRow.sourceGroup.sourceUrl').take()
  const trimmedUrl = (((urlField && urlField.value) || '') + '').trim()
  const doSync = async (payload) => {
    const result = await $chrome.runtime.sendMessage(payload)
    if (!result) {
      $message.error('同步失败：Service Worker 无响应，请刷新扩展后重试')
      return
    }
    if (result.count >= 0) $message.success(result.message)
    else $message.warning(result.message)
  }
  if (trimmedUrl) {
    if (!trimmedUrl.startsWith('http')) {
      $message.error('源 URL 必须是 HTTP 或 HTTPS 地址')
      return
    }
    $self.state.syncing = true
    try {
      await doSync({ action: 'devtool:sync-cookies', sourceUrl: trimmedUrl })
    } catch (e) {
      $message.error('同步失败：' + ((e && e.message) || '未知错误'))
    } finally {
      $self.state.syncing = false
    }
    return
  }
  $self.state.syncing = true
  try {
    const tabs = (await $chrome.tabs.query({ currentWindow: true })) || []
    const httpTab = tabs.find((t) => t.url && t.url.startsWith('http') && t.active) || tabs.find((t) => t.url && t.url.startsWith('http'))
    if (!httpTab || !httpTab.id) {
      $message.warning('当前窗口没有 HTTP 页面，请先打开一个 HTTP 页面，或在上方输入源 URL 后再同步')
      return
    }
    await doSync({ action: 'devtool:sync-cookies', tabId: httpTab.id })
  } catch (e) {
    $message.error('同步失败：' + ((e && e.message) || '未知错误'))
  } finally {
    $self.state.syncing = false
  }
}
$effect(() => { $self.loadCookieSync() }, [])

const re = $self.address.entire.substring(0, $self.address.entire.lastIndexOf('cookieSyncSettingsDiv') + 'cookieSyncSettingsDiv'.length)
const rf = $self.query(re).take()
$props({
  onPressEnter: () => rf.handleSyncNow(),
})

const re = $self.address.entire.substring(0, $self.address.entire.lastIndexOf('cookieSyncSettingsDiv') + 'cookieSyncSettingsDiv'.length)
const rf = $self.query(re).take()
$effect(() => {
  $props({
    loading: rf.state.syncing,
    disabled: (rf.state.targets || []).length === 0,
  })
}, [rf.state.syncing, rf.state.targets])
$props({
  onClick: () => rf.handleSyncNow(),
})

const re = $self.address.entire.substring(0, $self.address.entire.lastIndexOf('cookieSyncSettingsDiv') + 'cookieSyncSettingsDiv'.length)
const rf = $self.query(re).take()
$props({ onClick: () => rf.showAddOrUpdateDialog(null) })

const re = $self.address.entire.substring(0, $self.address.entire.lastIndexOf('cookieSyncSettingsDiv') + 'cookieSyncSettingsDiv'.length)
const rf = $self.query(re).take()
$effect(() => {
  const row = $utils.getArrayFieldRow($self, 'ArrayTable')
  const p = (row && row.protocol) || 'http'
  $self.value = p + '://'
  $props({ color: p === 'https' ? 'green' : 'blue' })
}, [rf.state.targets])

const re = $self.address.entire.substring(0, $self.address.entire.lastIndexOf('cookieSyncSettingsDiv') + 'cookieSyncSettingsDiv'.length)
const rf = $self.query(re).take()
$effect(() => {
  const row = $utils.getArrayFieldRow($self, 'ArrayTable')
  $self.value = row ? row.domain : ''
}, [rf.state.targets])

const re = $self.address.entire.substring(0, $self.address.entire.lastIndexOf('cookieSyncSettingsDiv') + 'cookieSyncSettingsDiv'.length)
const rf = $self.query(re).take()
$effect(() => {
  const row = $utils.getArrayFieldRow($self, 'ArrayTable')
  $self.value = row ? row.protocol + '://' + row.domain : ''
}, [rf.state.targets])

const re = $self.address.entire.substring(0, $self.address.entire.lastIndexOf('cookieSyncSettingsDiv') + 'cookieSyncSettingsDiv'.length)
const rf = $self.query(re).take()
$props({ onClick: () => { const row = $utils.getArrayFieldRow($self, 'ArrayTable'); rf.showAddOrUpdateDialog(row) } })

const re = $self.address.entire.substring(0, $self.address.entire.lastIndexOf('cookieSyncSettingsDiv') + 'cookieSyncSettingsDiv'.length)
const rf = $self.query(re).take()
$props({ onConfirm: async () => { const row = $utils.getArrayFieldRow($self, 'ArrayTable'); await rf.handleDelete(row) } })

const re = $self.address.entire.substring(0, $self.address.entire.lastIndexOf('cookieSyncSettingsDiv') + 'cookieSyncSettingsDiv'.length)
const rf = $self.query(re).take()
$props({
  onCancel: () => { $self.componentProps.open = false },
  onOk: () => {
    $self.validate().then(async () => {
      const form = $self.value
      const exists = rf.state.targets.some((t) => t.domain === form.domain && t.protocol === form.protocol && t.id !== form.id)
      if (exists) {
        const dField = $self.query($self.address.entire + '.domain').take()
        if (dField) dField.setFeedback({ type: 'error', messages: ['该域名与协议组合已存在'] })
        return
      }
      const list = rf.state.targets.slice()
      const isEdit = !!form.id
      if (isEdit) {
        const next = { id: form.id, domain: form.domain, protocol: form.protocol }
        const idx = list.findIndex((t) => t.id === form.id)
        if (idx >= 0) list[idx] = next
        else list.push(next)
      } else {
        list.push({ id: 'cookie_sync_' + Date.now() + Math.random().toString(36).slice(2, 7), domain: form.domain, protocol: form.protocol })
      }
      try {
        await rf.saveCookieSync(list)
        rf.state.targets = list
        $message.success(isEdit ? '目标已更新' : '目标已新增')
        $self.componentProps.open = false
      } catch (e) {
        $message.error('保存失败')
      }
    }).catch((e) => $logger.info('校验失败', e))
  },
})
